// Collect all input items into a single row
const row = {};
for (const item of $input.all()) {
  Object.assign(row, item.json);
}

const issuesFixed = row.issues_fixed || 0;
const tokensUsed = row.tokens_used || 0;
const activeTenants = row.active_tenants || 0;
const newSignups = row.new_signups || 0;
const revenueCents = row.revenue_cents || 0;
const revenueDollars = (revenueCents / 100).toFixed(2);

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '📊 Weekly Usage Report' }
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: '*Period:* Past 7 days' }
    ]
  },
  { type: 'divider' },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Issues Fixed:*\n${issuesFixed}` },
      { type: 'mrkdwn', text: `*Tokens Consumed:*\n${tokensUsed.toLocaleString()}` }
    ]
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Active Tenants:*\n${activeTenants}` },
      { type: 'mrkdwn', text: `*New Signups:*\n${newSignups}` }
    ]
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Total Revenue:*\n$${revenueDollars}` }
    ]
  }
];

return [{
  json: {
    channel: '#syntaro-metrics',
    attachments: JSON.stringify([{
      color: '#2ECC71',
      blocks: blocks
    }])
  }
}];
